"""Render career/CAREER.md, a readable view of the career record.

Usage: python render.py [CAREER_DIR] [--today YYYY-MM-DD]

CAREER.md is generated: edit the YAML under career/data/ instead.
Its "Open items" section lists what a review should look at.
"""

import datetime
import sys
from pathlib import Path

sys.dont_write_bytecode = True  # never write __pycache__ into an installed skill folder

from careerlib import as_list, find_career_dir, load_record, text  # noqa: E402

HEADER = (
    "<!-- GENERATED by render.py from career/data/. Do not edit; your changes will be overwritten. -->\n"
)


def fmt_period(start, end):
    start, end = text(start), text(end)
    if not start and not end:
        return "dates not recorded"
    return f"{start or '?'} – {end or '?'}"


def fmt_metric(metric):
    unit = text(metric.get("unit"))
    if text(metric.get("value")):
        value = f"{metric.get('value')} {unit}".strip()
    else:
        value = f"{metric.get('before')} → {metric.get('after')} {unit}".strip()
    flags = [text(metric.get("confidence"))]
    if metric.get("user_confirmed") is not True:
        flags.append("not confirmed")
    source = text(metric.get("source"))
    tail = f"; source: {source}" if source else ""
    return f"{text(metric.get('name'))}: {value} ({', '.join(f for f in flags if f)}{tail})"


def bullet_line(bullet):
    mark = "" if bullet.get("status") == "confirmed" else " *(draft)*"
    return f"- {text(bullet.get('text'))}{mark}"


def items(values):
    return [text(v) for v in as_list(values) if text(v)]


def sub_list(label, values):
    values = items(values)
    if not values:
        return []
    return [f"- **{label}:**"] + [f"  - {v}" for v in values]


def nda_text(value):
    if value is True:
        return " (under NDA)"
    if value == "unknown":
        return " (NDA status unknown; don't name the client)"
    return ""


def open_items(record, accomplishments, today):
    lines = []
    for acc in accomplishments:
        title = text(acc.get("title")) or acc.get("id")
        status = acc.get("status")
        sub = []
        follow = acc.get("follow_up")
        if isinstance(follow, dict) and text(follow.get("due")) and text(follow["due"])[:7] <= today[:7]:
            sub.append(f"follow-up due {follow.get('due')}: {text(follow.get('ask'))}")
        if status != "draft" and not text((acc.get("period") or {}).get("start")):
            sub.append("dates unknown")
        drafts = [b for b in acc.get("bullets") or [] if b.get("status") != "confirmed"]
        if drafts and status != "draft":
            sub.append(f"{len(drafts)} draft bullet(s) awaiting approval")
        sub += [f"gap: {gap}" for gap in items(acc.get("gaps"))]
        if status in ("draft", "incomplete") or sub:
            lines.append(f"- **{title}** ({status})")
            lines += [f"  - {s}" for s in sub]

    # Gaps recorded on other entries.
    employers = record.get("employment", {}).get("employers") or []
    for employer in employers:
        for gap in items(employer.get("gaps")):
            lines.append(f"- Gap ({text(employer.get('display_name') or employer.get('legal_name'))}): {gap}")
        for role in employer.get("roles") or []:
            for gap in items(role.get("gaps")):
                lines.append(f"- Gap ({text(role.get('title'))}): {gap}")
    for key, field in (("education", "degree"), ("projects", "name"), ("skills", "name"),
                       ("recognition", "title"), ("learning", "topic"), ("certifications", "name")):
        for entry in record.get(key, {}).get(key) or []:
            for gap in items(entry.get("gaps")):
                lines.append(f"- Gap ({key}: {text(entry.get(field))}): {gap}")

    pending = record.get("log_pending") or []
    if pending:
        lines.append(f"- Work-log entries not yet captured ({len(pending)}): see log.md")

    # Structural gaps.
    skill_names = {text(s.get("name")).lower() for s in record.get("skills", {}).get("skills") or []}
    used = sorted({text(t) for a in accomplishments for t in as_list(a.get("technologies"))
                   if text(t) and text(t).lower() not in skill_names})
    if used:
        lines.append(f"- Technologies used in accomplishments but missing from skills: {', '.join(used)}")
    unevidenced = [text(s.get("name")) for s in record.get("skills", {}).get("skills") or []
                   if not as_list(s.get("evidence"))]
    if unevidenced:
        lines.append(f"- Skills with no evidence ({len(unevidenced)}): {', '.join(unevidenced)}")
    role_ids_with_work = {a.get("role_id") for a in accomplishments}
    for employer in employers:
        for role in employer.get("roles") or []:
            if role.get("id") not in role_ids_with_work:
                lines.append(f"- No accomplishments captured for {text(role.get('title'))} at "
                             f"{text(employer.get('display_name') or employer.get('legal_name'))}")
    profile = record.get("profile", {})
    missing_profile = [k for k in ("name", "location", "email") if not text(profile.get(k))]
    if missing_profile:
        lines.append(f"- Profile missing: {', '.join(missing_profile)}")
    for key, label in (("employment", "employers"), ("education", "education"), ("projects", "projects")):
        inner = "employers" if key == "employment" else key
        if not record.get(key, {}).get(inner):
            lines.append(f"- Nothing recorded yet: {label}")
    goals = record.get("goals", {})
    if not any(as_list(goals.get(k)) for k in ("target_roles", "short_term", "medium_term", "long_term")):
        lines.append("- No goals recorded (target roles help decide what to capture first)")
    return lines


def render_accomplishment(acc):
    lines = [f"\n##### {text(acc.get('title')) or acc.get('id')}\n",
             f"`{acc.get('id')}` · {text(acc.get('status'))} · {text(acc.get('category'))} · "
             + (f"{text(acc.get('origin')).replace('_', ' ')} · " if text(acc.get('origin')) else "")
             + f"{fmt_period((acc.get('period') or {}).get('start'), (acc.get('period') or {}).get('end'))}\n"]
    for label, key in (("Situation", "situation"), ("Task", "task")):
        if text(acc.get(key)):
            lines.append(f"- **{label}:** {text(acc.get(key))}")
    lines += sub_list("Actions", acc.get("actions"))
    for label, key in (("Team", "team_context"), ("Scale", "scale"), ("Outcome", "outcome")):
        if text(acc.get(key)):
            lines.append(f"- **{label}:** {text(acc.get(key))}")
    if acc.get("technologies"):
        lines.append(f"- **Technologies:** {', '.join(items(acc['technologies']))}")
    for metric in acc.get("metrics") or []:
        lines.append(f"- **Metric:** {fmt_metric(metric)}")
    evidence = [f"{text(e.get('type'))}: {text(e.get('ref'))}" for e in acc.get("evidence") or [] if isinstance(e, dict)]
    lines += sub_list("Evidence", evidence)
    signals = acc.get("sde2_signals") or {}
    lines += sub_list("SDE-2 signals", [f"{k.replace('_', ' ')}: {v}" for k, v in signals.items() if text(v)])
    interview = acc.get("interview") or {}
    depth = [f"{k.replace('_', ' ')}: {v}" for k, v in interview.items() if k != "competencies" and text(v)]
    if items(interview.get("competencies")):
        depth.append(f"competencies: {', '.join(items(interview['competencies']))}")
    lines += sub_list("Interview depth", depth)
    lines += sub_list("Gaps", acc.get("gaps"))
    bullets = acc.get("bullets") or []
    if bullets:
        lines.append("- **Resume bullets:**")
        lines.extend("  " + bullet_line(b) for b in bullets)
    return lines


def render(record, today):
    out = [HEADER, "# Career Record\n"]
    profile = record.get("profile", {})
    employment = record.get("employment", {}).get("employers") or []
    accomplishments = [data for _, data in record["accomplishments"]]

    out.append("## Profile\n")
    links = profile.get("links") or {}
    contact = [text(profile.get(k)) for k in ("location", "email", "phone")] + [text(v) for v in links.values()]
    out.append(f"**{text(profile.get('name')) or '(name not set)'}**  ")
    out.append(" · ".join(c for c in contact if c) or "(contact details not set)")
    out.append("")
    for headline in profile.get("headlines") or []:
        out.append(bullet_line(headline))
    out.append("")

    out.append("## Open items\n")
    open_lines = open_items(record, accomplishments, today)
    out.append("\n".join(open_lines) if open_lines else "Nothing open.")
    out.append("")

    out.append("## Experience\n")
    role_ids = set()
    for employer in employment:
        out.append(f"### {text(employer.get('legal_name'))}\n")
        for role in employer.get("roles") or []:
            role_ids.add(role.get("id"))
            out.append(f"#### {text(role.get('title'))} ({text(role.get('type'))}, "
                       f"{fmt_period(role.get('start'), role.get('end'))})\n")
            if text(role.get("summary")):
                out.append(text(role.get("summary")) + "\n")
            for eng in role.get("engagements") or []:
                details = ", ".join(text(eng.get(k)) for k in ("domain", "scale") if text(eng.get(k)))
                out.append(f"- Client: {text(eng.get('client_descriptor'))}{nda_text(eng.get('nda'))}"
                           + (f" — {details}" if details else ""))
            out += sub_list("Notes", role.get("notes"))
            role_accs = [a for a in accomplishments if a.get("role_id") == role.get("id")]
            role_accs.sort(key=lambda a: (text((a.get("period") or {}).get("start")), text(a.get("title"))))
            role_accs.reverse()
            for acc in role_accs:
                out.extend(render_accomplishment(acc))
            out.append("")
    orphans = [a for a in accomplishments if a.get("role_id") not in role_ids]
    if orphans:
        out.append("### Not linked to a role\n")
        for acc in orphans:
            out.extend(render_accomplishment(acc))
        out.append("")

    out.append("## Skills\n")
    by_category = {}
    for skill in record.get("skills", {}).get("skills") or []:
        by_category.setdefault(text(skill.get("category")) or "other", []).append(skill)
    for category in sorted(by_category):
        names = [f"{text(s.get('name'))} ({len(as_list(s.get('evidence')))} evidence)" for s in by_category[category]]
        out.append(f"- **{category}:** {', '.join(names)}")
    out.append("")

    out.append("## Projects\n")
    for project in record.get("projects", {}).get("projects") or []:
        link_text = " · ".join(text(v) for v in (project.get("links") or {}).values() if text(v))
        out.append(f"### {text(project.get('name'))} ({text(project.get('type'))}, {text(project.get('status'))})\n")
        for label, key in (("Purpose", "purpose"), ("Role", "role"), ("Outcome", "outcome")):
            if text(project.get(key)):
                out.append(f"- {label}: {text(project.get(key))}")
        if project.get("technologies"):
            out.append(f"- Technologies: {', '.join(items(project['technologies']))}")
        if link_text:
            out.append(f"- Links: {link_text}")
        out += sub_list("Notes", project.get("notes"))
        for bullet in project.get("bullets") or []:
            out.append("  " + bullet_line(bullet))
        out.append("")

    out.append("## Education\n")
    for entry in record.get("education", {}).get("education") or []:
        score = entry.get("score") or {}
        score_text = ""
        if score:
            scale = f"/{score.get('scale')}" if text(score.get("scale")) else ""
            score_text = f", {text(score.get('type'))} {text(score.get('value'))}{scale}"
        field = f" {text(entry.get('field'))}" if text(entry.get("field")) else ""
        out.append(f"- {text(entry.get('degree'))}{field}, {text(entry.get('institution'))} "
                   f"({fmt_period(entry.get('start'), entry.get('end'))}{score_text})")
    out.append("")

    for key, title, field, detail_keys in (
            ("certifications", "Certifications", "name", ("issuer",)),
            ("recognition", "Recognition", "title", ("by", "description")),
            ("learning", "Learning", "topic", ("why", "what"))):
        out.append(f"## {title}\n")
        for entry in record.get(key, {}).get(key) or []:
            details = " — ".join(text(entry.get(k)) for k in detail_keys if text(entry.get(k)))
            date = text(entry.get("issued") or entry.get("date"))
            draft = " *(draft)*" if entry.get("status") == "draft" else ""
            out.append(f"- {text(entry.get(field))}" + (f" — {details}" if details else "")
                       + (f" ({date})" if date else "") + draft)
        out.append("")

    goals = record.get("goals", {})
    out.append("## Goals (aspirations, not evidence)\n")
    for key in ("target_roles", "target_employers", "short_term", "medium_term", "long_term"):
        values = items(goals.get(key))
        if values:
            out.append(f"- **{key.replace('_', ' ')}:** {'; '.join(values)}")
    out.append("")
    return "\n".join(out).rstrip() + "\n"


def main(argv):
    args = argv[1:]
    today = datetime.date.today().isoformat()
    if "--today" in args:
        i = args.index("--today")
        today = args[i + 1]
        del args[i:i + 2]
    career_dir = find_career_dir(args[0] if args else "career")
    record, errors = load_record(career_dir)
    if errors:
        for message in errors:
            print(f"error: {message}")
        print("Fix these (run validate.py) before rendering.")
        return 1
    target = Path(career_dir) / "CAREER.md"
    target.write_text(render(record, today), encoding="utf-8")
    print(f"wrote {target}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
